import { cookies } from 'next/headers'
import { toggleNotificationPreference } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get('notification-preference')?.value === 'on'
  const preference = enabled ? 'on' : 'off'

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notification preference: <strong>{preference}</strong>
      </p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
